mapper.select:
SELECT id,company_name,company_address,contact_name,
contact_mobile,contact_address,currency,company_state,create_time
FROM sys_accounting_company  sac WHERE delete_state=1

    AND sac.company_state =#{params.state}


    AND sac.company_name LIKE concat('%',#{params.searchKeyword},'%')


    AND sac.create_time >=#{params.startTime}


    AND sac.create_time <=#{params.startTime}

ORDER BY update_time DESC
